function ff_site_guide_snippet_link( $title ) {
	$found = get_posts( array( 'post_type' => 'wpcode', 'title' => $title, 'post_status' => array( 'publish', 'draft' ), 'numberposts' => 1 ) );
	if ( ! $found ) {
		return ff_site_guide_badge( 'warn', 'Snippet missing: ' . $title );
	}
	$link = '<a href="' . esc_url( admin_url( 'admin.php?page=wpcode-snippet-manager&snippet_id=' . (int) $found[0]->ID ) ) . '">' . esc_html( $title ) . '</a>';
	return 'publish' === $found[0]->post_status ? $link : $link . ' ' . ff_site_guide_badge( 'warn', 'Inactive' );
}

/**
 * Published Elementor documents containing a V4 form, with whether both spam-trap fields are present.
 */
function ff_site_guide_forms() {
	global $wpdb;
	$rows  = $wpdb->get_results(
		$wpdb->prepare(
			"SELECT p.ID, p.post_title, pm.meta_value FROM {$wpdb->posts} p
			 INNER JOIN {$wpdb->postmeta} pm ON pm.post_id = p.ID AND pm.meta_key = '_elementor_data'
			 WHERE p.post_status = 'publish' AND pm.meta_value LIKE %s
			 ORDER BY p.post_title",
			'%' . $wpdb->esc_like( '"elType":"e-form"' ) . '%'
		)
	);
	$forms = array();
	foreach ( $rows as $row ) {
		$forms[] = array(
			'id'    => (int) $row->ID,
			'title' => $row->post_title,
			'trap'  => false !== strpos( $row->meta_value, 'ff-hp-website' ) && false !== strpos( $row->meta_value, 'ff-hp-ts' ),
		);
	}
	return $forms;
}

